$(function(){function dateDisplay(v){if(!v)return '—';const p=String(v).slice(0,10).split('-');return p.length===3?`${p[2]}-${p[1]}-${p[0]}`:v;}let editingId=null,updateUrl=null;const formModal=new bootstrap.Modal('#returnModal'),productsModal=new bootstrap.Modal('#returnProductsModal');const table=$('#returnTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:{url:@json(route('super.return-to-warehouse.dt')),data:d=>{d.from_date=$('#from_date').val();d.to_date=$('#to_date').val()}},columns:[{data:'id',orderable:false,searchable:false,render:(d,t,r,m)=>m.row+m.settings._iDisplayStart+1},{data:'actions',orderable:false,searchable:false,className:'text-center'},{data:'number',name:'document.number'},{data:'return_date',name:'document.return_date',render:dateDisplay},{data:'mo',orderable:false},{data:'style',orderable:false},{data:'po_supplier',orderable:false},{data:'code',name:'product.code'},{data:'name',name:'product.name'},{data:'unit',orderable:false},{data:'quantity',name:'quantity',className:'text-end'},{data:'description',name:'description'}],order:[[3,'desc']],drawCallback:()=>window.feather&&feather.replace()});const productTable=$('#returnProductsTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:@json(route('super.return-to-warehouse.products.dt')),columns:[{data:'code',name:'code'},{data:'name',name:'name'},{data:'unit_label',orderable:false,searchable:false},{data:'actions',orderable:false,searchable:false,className:'text-center'}],drawCallback:()=>window.feather&&feather.replace()});$('#addProductionReturn').on('click',()=>{editingId=null;updateUrl=null;$('#returnForm')[0].reset();$('#returnProductId,#returnProductLabel').val('');$('#returnNumber').val('');$.get(@json(route('super.return-to-warehouse.number-preview'))).done(r=>$('#returnNumber').val(r.number));formModal.show()});$('#chooseReturnProduct').on('click',()=>{productTable.ajax.reload();productsModal.show()});$(document).on('click','.btn-select-return-product',function(){const b=$(this);$('#returnProductId').val(b.data('id'));$('#returnProductLabel').val(`${b.data('code')} — ${b.data('name')} (${b.data('unit')})`);productsModal.hide()});$('#filterReturn').on('click',()=>table.ajax.reload());$('#exportReturn').on('click',function(e){e.preventDefault();const u=new URL(this.href);u.searchParams.set('from_date',$('#from_date').val());u.searchParams.set('to_date',$('#to_date').val());location.href=u});$(document).on('click','.btn-edit-production-return',function(){const b=$(this);updateUrl=b.data('update-url');$.get(b.data('url')).done(d=>{const i=d.items[0];editingId=i.id;$('#returnForm [name=return_date]').val(d.date);$('#returnNumber').val(d.number);$('#returnProductId').val(i.product_id);$('#returnProductLabel').val(`${i.code} — ${i.name} (${i.unit||''})`);$('#returnForm [name=quantity]').val(i.quantity);$('#returnForm [name=raw_material_order_document_id]').val(d.mo_id||'');$('#returnForm [name=po_supplier_number]').val(d.po_supplier||'');$('#returnForm [name=description]').val(i.description||'');$('#returnModal .modal-title').text(@json(__('ui.common.edit'))+' '+@json(__('ui.production_return.return_title')));formModal.show()})});$('#returnModal').on('hidden.bs.modal',()=>$('#returnModal .modal-title').text(@json(__('ui.production_return.add'))));$('#returnForm').on('submit',function(e){e.preventDefault();const b=$('#saveReturn').prop('disabled',true);$.ajax({url:editingId?updateUrl:@json(route('super.return-to-warehouse.store')),method:editingId?'PUT':'POST',data:$(this).serialize()}).done(r=>{formModal.hide();table.ajax.reload(null,false);Swal.fire({icon:'success',text:r.number?`${r.message} (${r.number})`:r.message})}).fail(x=>Swal.fire({icon:'error',text:Object.values(x.responseJSON?.errors||{}).flat().join('\n')||x.responseJSON?.message||'Error'})).always(()=>b.prop('disabled',false))});$(document).on('click','.btn-delete-production-return',function(){const b=$(this);Swal.fire({icon:'warning',title:@json(__('ui.common.confirm_delete')),showCancelButton:true,confirmButtonText:@json(__('ui.common.delete')),cancelButtonText:@json(__('ui.common.cancel'))}).then(r=>{if(r.isConfirmed)$.ajax({url:b.data('url'),method:'DELETE',data:{_token:@json(csrf_token())}}).done(()=>table.ajax.reload(null,false)).fail(x=>Swal.fire({icon:'error',text:x.responseJSON?.message||'Error'}))})})});
</script>@endpush
